-- =============================================================================
-- 524 — LE CAHIER D'EXERCICES DE 1RE (partie 12)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 524 --niveau 1re --fichiers francais.n11b,francais.n12a,francais.n12b,francais.n13a,francais.n13b --suffixe 12 > supabase/contenu/524_exercices_1re_12.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n11b           18 exercices · 6 chapitres
--   francais.n12a           18 exercices · 6 chapitres
--   francais.n12b           18 exercices · 6 chapitres
--   francais.n13a           18 exercices · 6 chapitres
--   francais.n13b           18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('64ce5f70-3206-5385-b6e6-6dab66cf3e0a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Werst, 1892 : un roman, une invention","competence":"analyser-document","situation":"Tu prépares une fiche sur *Le Château des Carpathes* de Jules Verne. Lis la carte du roman, puis le tableau de ses personnages.","documents":[{"id":"carte","type":"fiche","modele":"affiche","entete":"Le Château des Carpathes","sousTitre":"Jules Verne","emoji":"🏰","lignes":[{"texte":"Publication","valeur":"1892","id":"z1"},{"texte":"Collection","valeur":"Les Voyages extraordinaires, chez Hetzel"},{"texte":"Lieu","valeur":"Werst, en Transylvanie"},{"texte":"Invention récente","valeur":"Le phonographe d’Edison, inventé en 1877","id":"z2"}],"pied":"Un château, une voix","teinte":"violet"},{"id":"pers","type":"tableau","titre":"Quelques personnages","colonnes":["Personnage","Son rôle"],"lignes":[["Rodolphe de Gortz","Le baron mélomane, obsédé par une voix"],["Orfanik","?"],["Franz de Télek","L’amant romantique, que la vérité brise"],["Maître Koltz","Le premier magistrat du village, superstitieux"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » pour Orfanik ?","aide":"Il fabrique les machines dont le baron a besoin.","type":"choix","options":[{"id":"a","texte":"Le savant inventeur au service de Gortz, génie des machines"},{"id":"b","texte":"Le berger qui aperçoit de la fumée au-dessus du château"},{"id":"c","texte":"La cantatrice célèbre morte sur scène cinq ans plus tôt"},{"id":"d","texte":"Le forestier qui revient paralysé de sa première expédition"}],"multiple":false},{"enonce":"Touche la case du personnage qui est superstitieux comme les villageois.","aide":"Cherche le premier magistrat du village.","type":"zone","document":"pers","multiple":false},{"enonce":"Combien d’années séparent l’invention du phonographe de la parution du roman ?","aide":"Utilise les deux dates de la fiche.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Orfanik est le **savant inventeur** au service de Gortz, un **génie des machines**."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Maître Koltz**, premier magistrat de Werst, est superstitieux comme tous les villageois."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ans","explication":"1892 − 1877 = **15 ans** : le phonographe est encore une merveille récente."}]$ex$::jsonb),
  ('64ce5f70-3206-5385-b6e6-6dab66cf3e0a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le fantôme qu’on démonte","competence":"analyser-document","situation":"Au début, le château de Werst semble hanté. À la fin, tout s’explique. Suis les étapes du roman, puis relie chaque apparence à sa vraie cause.","documents":[{"id":"fil","type":"chaine","titre":"Les étapes du récit","disposition":"colonne","noeuds":[{"id":"z1","texte":"Les villageois de Werst redoutent le château"},{"id":"z2","texte":"Nic Deck monte au château et revient paralysé"},{"id":"z3","texte":"Franz monte et croit entendre La Stilla"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Le château saute ; Franz sombre dans la folie"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Avant l’explosion, le lecteur comprend d’où vient la voix.","type":"choix","options":[{"id":"a","texte":"Un orage détruit les machines d’Orfanik avant la découverte"},{"id":"b","texte":"Les villageois pillent le château et partagent un trésor"},{"id":"c","texte":"Gortz est démasqué : voix enregistrée, image projetée par des miroirs"},{"id":"d","texte":"Franz retrouve La Stilla vivante, cachée dans une chambre"}],"multiple":false},{"enonce":"Touche l’étape où l’amoureux de La Stilla paie le prix de la vérité.","aide":"Franz est brisé par ce qu’il découvre.","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque apparence à sa cause technique ou humaine.","aide":"Le roman remplace chaque mystère par une explication.","type":"association","gauche":[{"id":"g0","texte":"La voix de La Stilla"},{"id":"g1","texte":"L’image de La Stilla"},{"id":"g2","texte":"Les machines du château"},{"id":"g3","texte":"Tout le dispositif"}],"droite":[{"id":"d0","texte":"Une projection par un jeu de miroirs"},{"id":"d1","texte":"Orfanik, le génie des machines"},{"id":"d2","texte":"Un enregistrement sur phonographes"},{"id":"d3","texte":"L’obsession de Gortz pour une voix"}]},{"enonce":"Complète la fin du roman.","aide":"La fin n’est pas tragique pour Franz.","type":"trous","segments":["Franz sombre dans la ",0," avant de ",1,"."],"banque":["folie","colère","guérir","mourir"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"La vérité éclate : Gortz a fait **enregistrer la voix** sur des phonographes et **projette l’image** par un jeu de **miroirs**."},{"cle":{"type":"zone","ids":["z5"]},"explication":"Le château saute et Franz **sombre dans la folie** avant de guérir."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"La **voix** vient des phonographes, l’**image** des miroirs, les **machines** d’Orfanik ; l’**obsession de Gortz** met tout en mouvement."},{"cle":{"type":"trous","trous":[["folie"],["guerir"]]},"affichage":"folie · guérir","explication":"Franz sombre dans la **folie**, puis **guérit**."}]$ex$::jsonb),
  ('64ce5f70-3206-5385-b6e6-6dab66cf3e0a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Pas fantastique, seulement romanesque","competence":"argumenter","situation":"Un roman peut-il faire peur et tout expliquer ? Lis un passage écrit pour l’exercice, à la manière de Verne, puis la phrase par laquelle le roman se commente.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Dans la salle du château","blocs":["Franz s’était arrêté, le cœur battant. Une voix s’élevait, pure, plus belle que toutes celles qu’il avait entendues ; près de la fenêtre, une forme blanche se dessinait.","Il ignorait qu’un phonographe, caché derrière la cloison, lui renvoyait cette voix, et qu’un miroir savamment placé composait l’apparition."],"source":"Texte écrit pour l’exercice, à la manière de Jules Verne"},{"id":"mot","type":"texte","genre":"recit","titre":"Une phrase du roman","blocs":["Cette histoire n’est pas fantastique, elle n’est que romanesque."],"source":"Jules Verne, *Le Château des Carpathes* (1892)"}],"questions":[{"enonce":"Touche les deux objets qui produisent l’apparition.","aide":"L’un renvoie la voix, l’autre fabrique l’image.","type":"zone","document":"scene","multiple":true},{"enonce":"Que veut dire Verne par « pas fantastique, seulement romanesque » ?","aide":"Reviens aux deux objets du passage : sont-ils magiques ?","type":"choix","options":[{"id":"a","texte":"Les esprits existent mais le roman choisit de les taire"},{"id":"b","texte":"Le roman n’a rien de romanesque et relève du reportage"},{"id":"c","texte":"Le récit est invraisemblable et ne doit pas être cru"},{"id":"d","texte":"Tout s’explique par la technique et par un amour fou"}],"multiple":false},{"enonce":"Range chaque élément : relève-t-il de la superstition du village, ou de la science de Gortz ?","aide":"Demande-toi : est-ce une croyance, ou un dispositif fabriqué ?","type":"categories","categories":[{"id":"c0","texte":"La superstition du village"},{"id":"c1","texte":"La science de Gortz"}],"items":[{"id":"i0","texte":"L’image projetée par un jeu de miroirs"},{"id":"i1","texte":"La voix enregistrée sur phonographes"},{"id":"i2","texte":"Le château serait hanté"},{"id":"i3","texte":"Orfanik, génie des machines"},{"id":"i4","texte":"Maître Koltz, premier magistrat superstitieux"}]},{"enonce":"Relie chaque thème du roman à ce qui l’illustre.","aide":"Pense à ce que le roman montre dans chaque cas.","type":"association","gauche":[{"id":"g0","texte":"Le fantastique expliqué"},{"id":"g1","texte":"Science et superstition"},{"id":"g2","texte":"Le deuil et la reproduction"},{"id":"g3","texte":"Une réflexion sur l’image"}],"droite":[{"id":"d0","texte":"Le village croit aux esprits, le lecteur découvre des machines"},{"id":"d1","texte":"Elle survit à la personne, avant même le cinéma"},{"id":"d2","texte":"Un décor gothique mais rationalisé"},{"id":"d3","texte":"Aimer une voix enregistrée, c’est refuser la mort"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34","m46"]},"explication":"Le **phonographe** produit la voix, le **miroir** l’image : la technique fabrique le surnaturel."},{"cle":{"type":"choix","ids":["d"]},"explication":"Pour Verne, le fantastique est **démonté par la technique** : ni esprit ni fantôme, seulement des machines et un amour fou."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Les **villageois** croient aux esprits ; **Gortz et Orfanik** fabriquent le surnaturel avec phonographes et miroirs."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"Verne **rationalise** le décor gothique, oppose **science et superstition**, lie le **deuil** à la reproduction, et annonce le **cinéma** par la réflexion sur l’image."}]$ex$::jsonb),
