   $ex${"titre":"Deux pères, deux enfants, une gifle","competence":"analyser-document","situation":"Tu prépares la fiche du *Cid* de Corneille. Pour comprendre le conflit, repère d’abord qui est lié à qui.","documents":[{"id":"fil","type":"chaine","titre":"Les liens entre les personnages","disposition":"ligne","noeuds":[{"id":"z1","texte":"Don Diègue"},{"id":"z2","texte":"Rodrigue"},{"id":"z3","texte":"Chimène"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2","texte":"père de"},{"de":"z2","a":"z3","texte":"aime"},{"de":"z3","a":"z4","texte":"fille de"}]}],"questions":[{"enonce":"Qui faut-il écrire dans la case « ? » ?","aide":"Le père de Chimène est celui qui commet l’affront.","type":"choix","options":[{"id":"a","texte":"Don Fernand, le roi de Castille, arbitre qui temporise"},{"id":"b","texte":"Don Sanche, soupirant de Chimène et champion malheureux"},{"id":"c","texte":"L’Infante, qui aime Rodrigue mais y renonce"},{"id":"d","texte":"Don Gomès, le père de Chimène, qui gifle don Diègue"}],"multiple":false},{"enonce":"Touche le personnage qui, trop vieux pour se venger, demande à son fils de le faire.","aide":"C’est le père de Rodrigue.","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque personnage à son conflit.","aide":"Chaque personnage est partagé entre deux forces, sauf le roi.","type":"association","gauche":[{"id":"g0","texte":"Rodrigue"},{"id":"g1","texte":"Chimène"},{"id":"g2","texte":"L’Infante"},{"id":"g3","texte":"Don Fernand"}],"droite":[{"id":"d0","texte":"Elle aime Rodrigue mais renonce : il n’est pas de son rang"},{"id":"d1","texte":"L’honneur de sa famille contre son amour"},{"id":"d2","texte":"Le roi de Castille, arbitre qui temporise"},{"id":"d3","texte":"Le devoir de venger son père contre son amour"}]},{"enonce":"Complète avec le genre de la pièce.","aide":"Le cours précise le genre d’abord, puis le genre des éditions suivantes.","type":"trous","segments":["À sa création en 1637, la pièce est une ",0," ; elle devient ensuite une ",1,"."],"banque":["farce","comédie","tragédie","tragi-comédie"]}]}$ex$::jsonb,
