  ('f05bd74c-60e2-57ca-9da8-9695dcaac366'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Percé jusques au fond du cœur","competence":"analyser-texte","situation":"Rodrigue vient d’apprendre que son père a été giflé. Lis le début de ses stances, puis le tableau des étapes de l’action.","documents":[{"id":"stances","type":"texte","genre":"poeme","titre":"Le début des stances","blocs":["Percé jusques au fond du cœur","D’une atteinte imprévue aussi bien que mortelle,"],"source":"Pierre Corneille, *Le Cid* (1637), acte I, scène 6"},{"id":"etapes","type":"tableau","titre":"Les premières étapes","colonnes":["Étape","Ce qui se passe"],"lignes":[["L’affront","Don Gomès gifle don Diègue, trop vieux pour se venger"],["Le dilemme","?"],["L’acte","Rodrigue tue le père de Chimène en duel"],["Le devoir de Chimène","Elle réclame au roi la mort de Rodrigue, tout en l’aimant"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme le coup qui frappe Rodrigue.","aide":"C’est un coup « imprévu et mortel ».","type":"zone","document":"stances","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » du tableau ?","aide":"Après l’affront, le père s’adresse à son fils.","type":"choix","options":[{"id":"a","texte":"Don Diègue demande à son fils de laver l’affront"},{"id":"b","texte":"Don Fernand ordonne à Rodrigue de quitter la Castille"},{"id":"c","texte":"L’Infante révèle à Rodrigue qu’elle l’aime en secret"},{"id":"d","texte":"Chimène supplie Rodrigue de ne pas se battre en duel"}],"multiple":false},{"enonce":"Range chaque élément : pousse-t-il Rodrigue à frapper, ou le retient-il ?","aide":"Cherche d’un côté ce qui touche son père, de l’autre ce qui touche Chimène.","type":"categories","categories":[{"id":"c0","texte":"Ce qui le pousse à frapper"},{"id":"c1","texte":"Ce qui le retient"}],"items":[{"id":"i0","texte":"Son amour pour Chimène"},{"id":"i1","texte":"L’honneur de sa famille"},{"id":"i2","texte":"Le fait que don Gomès est le père de Chimène"},{"id":"i3","texte":"La gifle donnée à don Diègue"}]},{"enonce":"Complète avec le 