s":[{"id":"i0","texte":"Dire « Va, je ne te hais point »"},{"id":"i1","texte":"Aimer toujours Rodrigue"},{"id":"i2","texte":"Vouloir venger son père"},{"id":"i3","texte":"Réclamer au roi la mort de Rodrigue"}]},{"enonce":"Relie chaque notion à ce qu’elle désigne.","aide":"Chaque notion renvoie à un moment ou à un enjeu de la pièce.","type":"association","gauche":[{"id":"g0","texte":"Le dilemme cornélien"},{"id":"g1","texte":"Le héros cornélien"},{"id":"g2","texte":"La fin ouverte"},{"id":"g3","texte":"Le reproche de l’Académie"}],"droite":[{"id":"d0","texte":"Le mariage est différé d’un an"},{"id":"d1","texte":"Chimène épouserait le meurtrier de son père"},{"id":"d2","texte":"Il se grandit en choisissant le devoir sans cesser d’aimer"},{"id":"d3","texte":"Deux valeurs également hautes et un choix qui coûte"}]}]}$ex$::jsonb,
