   $ex${"titre":"Rêve ou réel ?","competence":"argumenter","situation":"Pour ton oral, deux camarades se disputent sur la fête du domaine : est-elle un rêve, ou le roman la tient-il pour réelle ? Départage-les avec le tableau.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"La fête, c’est un rêve : Meaulnes ne retrouve jamais le chemin, donc le domaine n’a jamais existé."},{"qui":"Théo","texte":"Rien ne le prouve. Le roman garde un ancrage réaliste : l’école, la Sologne, les saisons. Il ne tranche jamais tout à fait."}]},{"id":"tab","type":"tableau","titre":"Ce que le roman installe","colonnes":["Ce qu’on lit","Ce que ça installe"],"lignes":[["L’école, la Sologne, les saisons","Le réalisme rural"],["Le domaine, la fête, la disparition","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot par lequel Théo s’oppose à l’idée d’un pur rêve.","aide":"Théo parle de ce qui rattache le roman au monde réel.","type":"zone","document":"deb","multiple":false},{"enonce":"Complète la case « ? » du tableau.","aide":"Pense à ce qui est merveilleux et un peu irréel.","type":"trous","segments":["Le domaine, la fête et la disparition installent une atmosphère de ",0,"."],"banque":["conte","reportage","catalogue"]},{"enonce":"Range chaque élément : il relève du réalisme rural, ou de l’atmosphère de conte ?","aide":"Demande-toi : cela pourrait-il se voir dans un village ordinaire ?","type":"categories","categories":[{"id":"c0","texte":"Réalisme rural"},{"id":"c1","texte":"Atmosphère de conte"}],"items":[{"id":"i0","texte":"La disparition de trois jours"},{"id":"i1","texte":"La Sologne et ses saisons"},{"id":"i2","texte":"L’école où enseigne le père de François"},{"id":"i3","texte":"Le domaine mystérieux"},{"id":"i4","texte":"La fête étrange"}]},{"enonce":"Que peut-on conclure du dialogue et du tableau ?","aide":"Cherche la réponse qui garde les deux colonnes du tableau.","type":"choix","options":[{"id":"a","texte":"Il se lit comme un pur conte, sans aucun ancrage réaliste"},{"id":"b","texte":"Il prouve que la fête n’a été qu’un rêve de Meaulnes"},{"id":"c","texte":"Il tient ensemble réalisme rural et atmosphère de conte"},{"id":"d","texte":"Il se lit comme un récit réaliste, sans aucun mystère"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Théo répond que le roman a un **ancrage** réaliste : il ne se réduit pas à un rêve."},{"cle":{"type":"trous","trous":[["conte"]]},"affichage":"conte","explication":"Ces éléments donnent une atmosphère de **conte**, qui s’ajoute au réalisme rural."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c1"}},"explication":"L’**école**, la **Sologne** et les saisons sont du réel ; le **domaine**, la **fête** et la **disparition** sont du conte."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le roman **tient ensemble** réalisme et conte, et **ne tranche jamais tout à fait** : c’est ce qui fait sa richesse."}]$ex$::jsonb),
