  ('234dde68-31c6-5ece-81f3-8f5194db34f0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les guépards cèdent la place","competence":"argumenter","situation":"Pour ton oral, relis ce passage écrit pour l’exercice, à la manière du roman, puis départage deux élèves sur la célèbre formule du livre.","documents":[{"id":"p","type":"texte","genre":"recit","titre":"Sur la terrasse","blocs":["Sur la terrasse de Donnafugata, un vieux prince regarde passer les voitures neuves. Le maire, fraîchement enrichi, a acheté les terres des voisins ruinés ; demain, il achètera leurs blasons. Le prince ne s’indigne pas : il sourit, un peu las. Les drapeaux changent, pense-t-il ; les maîtres changent de visage ; et les paysans, eux, continueront de payer."],"source":"Texte écrit pour l’exercice, à la manière du Guépard"},{"id":"d","type":"dialogue","titre":"La formule du roman","modele":"bulles","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Mehdi","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"« Il faut que tout change pour que rien ne change » : le prince est contre toute révolution."},{"qui":"Mehdi","texte":"Non : la formule dit que le pouvoir passe à d’autres sans que la société change."}]}],"questions":[{"enonce":"Touche le mot qui montre que l’argent remplace la naissance.","aide":"Qui possède les terres, au début du passage ?","type":"zone","document":"p","multiple":false},{"enonce":"D’après le passage, qui a raison ?","aide":"Que feront les paysans, une fois les drapeaux et les maîtres changés ?","type":"choix","options":[{"id":"a","texte":"Mehdi : les paysans profitent du changement de maîtres"},{"id":"b","texte":"Lina : le prince lutte contre le maire enrichi"},{"id":"c","texte":"Mehdi : le pouvoir change de mains, la société reste la même"},{"id":"d","texte":"Lina : le prince veut empêcher toute révolution"}],"multiple":false},{"enonce":"Touche le verbe qui dit ce qui ne change pas pour les paysans.","aide":"C’est le dernier mot de la phrase.","type":"zone","document":"p","multiple":false},{"enonce":"Relie chaque détail du passage à son effet.","aide":"Demande-toi ce que le détail révèle du ton, de la société, du changement.","type":"association","gauche":[{"id":"g0","texte":"Un prince qui sourit au lieu de s’indigner"},{"id":"g1","texte":"Des terres achetées, des blasons à venir"},{"id":"g2","texte":"Les drapeaux changent, les paysans paient"}],"droite":[{"id":"d0","texte":"La relève des élites par la bourgeoisie"},{"id":"d1","texte":"Un changement seulement apparent"},{"id":"d2","texte":"Une ironie mélancolique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Le maire a **acheté** les terres : la fortune neuve prend la place de la noblesse ruinée."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans le passage, les maîtres changent mais les paysans **continuent de payer** : c’est la lecture de **Mehdi**."},{"cle":{"type":"zone","ids":["m55"]},"explication":"Les paysans continueront de **payer** : leur sort ne change pas."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le sourire donne l’**ironie mélancolique**, l’achat des terres la **relève des élites**, et les paysans qui paient un **changement apparent**."}]$ex$::jsonb),
