   $ex${"titre":"Une vertu qui fait souffrir","competence":"argumenter","situation":"Pour ton oral, deux élèves se disputent : Henriette est-elle heureuse de renoncer ? Lis leur débat, puis un passage écrit pour l’exercice, à la manière de Balzac.","documents":[{"id":"d","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Maya","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"Henriette est vertueuse et sereine : le roman fait l’éloge du renoncement."},{"qui":"Théo","texte":"Au contraire : il montre la vertu comme une souffrance."}]},{"id":"l","type":"texte","genre":"lettre","titre":"La lettre d’Henriette","blocs":["« Vous m’avez cru froide ; j’étais brûlante. Chaque jour, j’ai refusé de vous le dire, et ce refus fut ma façon de vous aimer. »"],"source":"Lettre écrite pour l’exercice, à la manière de Balzac"}],"questions":[{"enonce":"Touche le mot par lequel Théo conteste l’idée d’une vertu sereine.","aide":"Cherche ce que la vertu fait à Henriette selon Théo.","type":"zone","document":"d","multiple":false},{"enonce":"Touche le mot qui montre que l’amour d’Henriette était vif.","aide":"Il s’oppose à « froide ».","type":"zone","document":"l","multiple":false},{"enonce":"Que prouve cette lettre à la manière de Balzac ?","aide":"Relis l’opposition entre « froide » et « brûlante ».","type":"choix","options":[{"id":"a","texte":"Henriette reproche à Félix son ambition et sa légèreté"},{"id":"b","texte":"Henriette regrette de ne pas avoir cédé à Félix plus tôt"},{"id":"c","texte":"Henriette a aimé de toute la force qu’elle refusait de montrer"},{"id":"d","texte":"Henriette n’a jamais aimé Félix et le lui avoue enfin"}],"multiple":false},{"enonce":"Range chaque élément : il appuie la lecture « la vertu est une souffrance », ou la lecture « la vertu est sereine » ?","aide":"Le roman montre-t-il Henriette apaisée ou déchirée ?","type":"categories","categories":[{"id":"c0","texte":"La vertu est une souffrance"},{"id":"c1","texte":"La vertu est sereine"}],"items":[{"id":"i0","texte":"Elle se laisse mourir de faim et de chagrin"},{"id":"i1","texte":"Elle impose le renoncement à Félix et à elle-même"},{"id":"i2","texte":"Henriette vit de la passion qu’elle réprime"},{"id":"i3","texte":"Elle goûte un bonheur calme loin du monde"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"Théo répond que la vertu est une **souffrance** : le roman ne l’admire pas, il la montre douloureuse."},{"cle":{"type":"zone","ids":["m7"]},"explication":"Henriette se dit **brûlante** : elle aime avec force, mais elle se tait."},{"cle":{"type":"choix","ids":["c"]},"explication":"La lettre dit que sous la **froideur** apparente, l’amour était **brûlant** : elle refusait seulement de le montrer."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Le roman montre le **déchirement** d’Henriette ; seule une lecture **contraire** au texte imaginerait un bonheur calme."}]$ex$::jsonb),
