   $ex${"titre":"La médecine, un pouvoir qui parle latin","competence":"argumenter","situation":"Pour ton oral, deux élèves se disputent sur la cible de la pièce. Lis le débat et ces deux répliques authentiques de Molière, puis tranche.","documents":[{"id":"d","type":"dialogue","titre":"La cible de la pièce","modele":"bulles","participants":[{"nom":"Sarah","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Sarah","texte":"La pièce se moque seulement d’Argan, un hypocondriaque."},{"qui":"Paul","texte":"Non : elle vise la médecine comme pouvoir : jargon, autorité, latin. Et on ne guérit Argan qu’en jouant."}]},{"id":"t","type":"texte","genre":"theatre","titre":"Deux moments de la pièce","blocs":[{"personnage":"Toinette, en médecin","replique":"Le poumon, le poumon, vous dis-je."},{"didascalie":"Dans la cérémonie finale, on reçoit Argan médecin, en faux latin."},{"personnage":"Le président","replique":"Dignus, dignus est entrare\nIn nostro docto corpore."}],"source":"Molière, Le Malade imaginaire (1673)"}],"questions":[{"enonce":"Touche le mot qui dit ce que Paul voit dans la cible de la pièce.","aide":"Paul parle de jargon, d’autorité, de latin.","type":"zone","document":"d","multiple":false},{"enonce":"Que montre la réplique de Toinette, déguisée en médecin ?","aide":"Toinette ne connaît rien à la médecine : que fait-elle pourtant ?","type":"choix","options":[{"id":"a","texte":"Un faux savant qui a réponse à tout, avec aplomb"},{"id":"b","texte":"Un médecin que le diagnostic inquiète vraiment"},{"id":"c","texte":"Un savant qui doute de ce qu’il affirme"},{"id":"d","texte":"Un vrai médecin qui hésite devant la maladie"}],"multiple":false},{"enonce":"Complète avec le dialogue.","aide":"Relis la fin de la réplique de Paul.","type":"trous","segments":["On ne guérit Argan qu’en ",0,"."],"banque":["jouant","lisant","payant"]},{"enonce":"Relie chaque moment de la pièce à ce qu’il met en scène.","aide":"Pense à ce que chaque scène révèle.","type":"association","gauche":[{"id":"g0","texte":"La fausse mort d’Argan"},{"id":"g1","texte":"Le faux médecin de Toinette"},{"id":"g2","texte":"La cérémonie en faux latin"}],"droite":[{"id":"d0","texte":"Le jargon qui donne l’autorité"},{"id":"d1","texte":"Un faux savoir qui parle avec aplomb"},{"id":"d2","texte":"Le théâtre fait apparaître la vérité"}]}]}$ex$::jsonb,
