  ('5b98293b-e3e3-52dd-8cf0-6eafe97f30c9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Chassé de chez Bertin","competence":"analyser-texte","situation":"Lis ce résumé de la rencontre, écrit pour l’exercice, puis retrouve les ressorts du dialogue et l’histoire du texte.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"La rencontre, résumée","blocs":["Au café de la Régence, MOI croise LUI, le neveu d’un compositeur célèbre. C’est un musicien raté, un pique-assiette qui doit sa table aux maisons riches.","Il vient d’être chassé de chez le financier Bertin pour avoir, une fois, dit une vérité à table. Il n’en tire aucune honte, et se vante même de sa bassesse."],"source":"Résumé écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Touche le mot qui désigne le lieu de la rencontre.","aide":"C’est un lieu public où l’on boit et où l’on cause.","type":"zone","document":"resume","multiple":false},{"enonce":"Touche le mot qui dit pourquoi le neveu a été chassé de chez Bertin.","aide":"Dans une maison riche, il a commis une imprudence de parole.","type":"zone","document":"resume","multiple":false},{"enonce":"Relie chaque élément à ce qu’il désigne.","aide":"Chaque terme est un mot-clé du cours : une thèse, un sous-titre, un protecteur, un traducteur.","type":"association","gauche":[{"id":"g0","texte":"La « pantomime des gueux »"},{"id":"g1","texte":"« Satire seconde »"},{"id":"g2","texte":"Bertin"},{"id":"g3","texte":"Goethe"}],"droite":[{"id":"d0","texte":"La posture qui convient au maître qu’on sert"},{"id":"d1","texte":"Le financier qui chasse le neveu"},{"id":"d2","texte":"Le traducteur du texte en allemand, en 1805"},{"id":"d3","texte":"Le sous-titre que Diderot donne à son texte"}]},{"enonce":"Remets en ordre l’histoire du texte.","aide":"Le texte voyage : écrit en français, il devient allemand avant de revenir au français.","type":"ordre","items":[{"id":"a","texte":"Goethe le traduit en allemand (1805)"},{"id":"b","texte":"Diderot l’écrit et le remanie (1761-1774)"},{"id":"c","texte":"Le texte revient en français"},{"id":"d","texte":"Il meurt sans l’avoir publié (1784)"}]}]}$ex$::jsonb,
