   $ex${"titre":"Le trombone, à la manière de Ponge","competence":"analyser-texte","situation":"Lis ce court texte écrit pour l’exercice, à la manière de Ponge, puis complète le programme du recueil.","documents":[{"id":"obj","type":"texte","genre":"recit","titre":"Le trombone","blocs":["Un fil d’acier plié trois fois sur lui-même : voilà tout le trombone.","Il ne sait que retenir. Deux feuilles, dix feuilles, il serre sans bruit et ne demande rien. Qu’on le jette, il se redresse à demi, comme un souvenir de ligne droite."],"source":"Texte écrit pour l’exercice, à la manière de Francis Ponge"},{"id":"prog","type":"tableau","titre":"Le programme du recueil","colonnes":["Ce que le poème refuse","Ce qu’il vise"],"lignes":[["Le lyrisme","La description exacte"],["Le symbole","?"],["Le « je » sentimental","Une définition-description"]],"enteteLignes":false}],"questions":[{"enonce":"Touche le mot qui dit de quoi le trombone est fait.","aide":"La description exacte commence par la matière de l’objet.","type":"zone","document":"obj","multiple":false},{"enonce":"Touche le verbe qui résume la fonction du trombone.","aide":"À quoi sert-il, quand il serre deux feuilles ?","type":"zone","document":"obj","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » : ce que le poème vise à la place du symbole ?","aide":"Refuser le symbole, c’est refuser que l’objet représente autre chose que lui.","type":"choix","options":[{"id":"a","texte":"L’objet comme image de l’âme du poète"},{"id":"b","texte":"L’objet pour lui-même"},{"id":"c","texte":"Une morale tirée de l’objet"},{"id":"d","texte":"Le souvenir personnel du poète"}],"multiple":false},{"enonce":"Relie chaque élément du cours à son rôle.","aide":"Il y a un texte du recueil, un manifeste, un soutien et un critique.","type":"association","gauche":[{"id":"g0","texte":"Le Cageot"},{"id":"g1","texte":"Le Galet"},{"id":"g2","texte":"Jean Paulhan"},{"id":"g3","texte":"Sartre"}],"droite":[{"id":"d0","texte":"Part d’un mot placé