   $ex${"titre":"Sécheresse ou exigence ?","competence":"argumenter","situation":"Deux élèves se disputent sur le refus du lyrisme chez Ponge. Départage-les avec le cours.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Hakim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Ponge refuse le « je » sentimental : il n’a donc pas de cœur pour ses objets."},{"qui":"Hakim","texte":"Il refuse l’effusion par exigence, pas par sécheresse : il veut rendre justice à ce qui n’a pas de voix."},{"qui":"Inès","texte":"Mais alors, où est la poésie ?"},{"qui":"Hakim","texte":"Dans le regard et dans le travail du mot."}]},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le refus du lyrisme n’est pas de la sécheresse","Le poème rend justice à ce qui n’a pas de voix","?"]],"enteteLignes":false}],"questions":[{"enonce":"Touche le mot par lequel Hakim explique le refus du lyrisme.","aide":"Hakim oppose ce mot à la « sécheresse » dont parle Inès.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Cherche un fait qui prouve que Ponge s’attache à l’objet sans effusion.","type":"choix","options":[{"id":"a","texte":"Ponge a longtemps été employé chez Hachette, aux messageries"},{"id":"b","texte":"« Le Cageot » finit par une tendresse pour cette chose méprisée"},{"id":"c","texte":"Sartre consacre un essai au poète en 1944, qui le fait connaître"},{"id":"d","texte":"Le recueil paraît chez Gallimard en 1942, grâce à Paulhan"}],"multiple":false},{"enonce":"Range chaque procédé : sert-il la description exacte, ou relève-t-il du lyrisme que Ponge écarte ?","aide":"Demande-toi si le procédé sert l’objet ou parle du poète.","type":"categories","categories":[{"id":"c0","texte":"Description exacte"},{"id":"c1","texte":"Lyrisme écarté"}],"item