en »"},{"id":"g2","texte":"Une accusation jamais nommée"}],"droite":[{"id":"d0","texte":"Le lecteur reste dans le même brouillard que K."},{"id":"d1","texte":"Une bureaucratie absurde, invisible, à laquelle on finit par consentir"},{"id":"d2","texte":"La parabole résume tout le roman en une page"}]}]}$ex$::jsonb,
